document.body.innerHTML="<section class=\"login-screen\" id=\"loginScreen\">\n    <div class=\"login-visual\">\n      <div class=\"brand-lockup\"><span class=\"logo login-logo\">N</span> NSL Bloggers</div>\n      <div class=\"login-copy\">\n        <h1>Все блогеры.<br>Вся экономика.<br>Один кабинет.</h1>\n        <p>Единая рабочая система отдела блогеров для Лиги Нутрициологии и FIT PRO.</p>\n      </div>\n      <div class=\"login-features\">\n        <span>База блогеров</span><span>Размещения</span><span>amoCRM</span><span>ROMI и ROI</span>\n      </div>\n    </div>\n    <div class=\"login-form-wrap\">\n      <form class=\"login-card\" id=\"loginForm\">\n        <h2 id=\"loginTitle\">Вход сотрудника</h2>\n        <p id=\"loginSubtitle\">Введите рабочую почту и пароль. Роль и история прошлых месяцев подключатся автоматически.</p>\n        <input type=\"hidden\" id=\"loginMode\" value=\"signin\">\n        <div class=\"login-fields\">\n          <div class=\"field\" id=\"loginEmailField\"><label>Рабочая почта</label><input class=\"input\" id=\"loginEmail\" type=\"email\" autocomplete=\"email\" placeholder=\"name@company.ru\"></div>\n          <div class=\"field\"><label id=\"loginPasswordLabel\">Пароль</label><input class=\"input\" id=\"loginPassword\" type=\"password\" autocomplete=\"current-password\" minlength=\"12\" placeholder=\"Не менее 12 символов\" required></div>\n          <div class=\"field hidden\" id=\"loginPasswordConfirmField\"><label>Повторите пароль</label><input class=\"input\" id=\"loginPasswordConfirm\" type=\"password\" autocomplete=\"new-password\" minlength=\"12\"></div>\n        </div>\n        <button class=\"btn btn-primary btn-block\" id=\"loginSubmitBtn\" type=\"submit\">Войти</button>\n        <div class=\"demo-hint\" id=\"loginMessage\"><b>Первый вход?</b> Администратор формирует персональную ссылку в разделе «Сотрудники».</div>\n        <div class=\"login-mode-note\">Доступ получают только сотрудники, заранее добавленные администратором.</div>\n      </form>\n    </div>\n  </section>\n\n  <div class=\"app-shell hidden\" id=\"appShell\">\n    <aside class=\"sidebar\" id=\"sidebar\">\n      <div class=\"side-brand\">\n        <div class=\"brand-lockup\"><span class=\"logo\">N</span><div>NSL Bloggers<small>Отдел блогеров</small></div></div>\n      </div>\n      <div class=\"side-section\">Обзор</div>\n      <nav class=\"nav\">\n        <button class=\"nav-btn active\" data-page=\"dashboard\"><span class=\"nav-icon\">⌂</span>Главная</button>\n        <button class=\"nav-btn\" data-page=\"profile\"><span class=\"nav-icon\">Я</span>Мой кабинет</button>\n      </nav>\n      <div class=\"side-section\">Рабочий цикл</div>\n      <nav class=\"nav\">\n        <button class=\"nav-btn\" data-page=\"bloggers\"><span class=\"nav-icon\">1</span>Блогеры<span class=\"nav-badge\" id=\"bloggerCountBadge\">0</span></button>\n        <button class=\"nav-btn\" data-page=\"placements\"><span class=\"nav-icon\">2</span>Размещения</button>\n        <button class=\"nav-btn\" data-page=\"calendar\"><span class=\"nav-icon\">3</span>Выходы</button>\n      </nav>\n      <div class=\"side-section\">Контроль</div>\n      <nav class=\"nav\">\n        <button class=\"nav-btn\" data-page=\"reports\"><span class=\"nav-icon\">4</span>Отчёты и охваты</button>\n        <button class=\"nav-btn leader-only\" data-page=\"finance\"><span class=\"nav-icon\">₽</span>Финансы</button>\n        <button class=\"nav-btn leader-only\" data-page=\"kpi\"><span class=\"nav-icon\">K</span>KPI и зарплата</button>\n      </nav>\n      <div class=\"side-section leader-only\">Настройки</div>\n      <nav class=\"nav\">\n        <button class=\"nav-btn leader-only\" data-page=\"team\"><span class=\"nav-icon\">С</span>Сотрудники</button>\n        <button class=\"nav-btn leader-only\" data-page=\"integrations\"><span class=\"nav-icon\">И</span>Интеграции<span class=\"nav-badge\">1</span></button>\n      </nav>\n      <div class=\"side-profile\">\n        <div class=\"avatar\" id=\"sideAvatar\">НС</div>\n        <div><strong id=\"sideUserName\">Сотрудник NSL</strong><small id=\"sideRole\">Сотрудник</small></div>\n        <button id=\"logoutBtn\" title=\"Выйти из кабинета\">↪</button>\n      </div>\n    </aside>\n    <div class=\"mobile-overlay\" id=\"mobileOverlay\"></div>\n\n    <main class=\"main\">\n      <header class=\"topbar\">\n        <button class=\"menu-btn\" id=\"menuBtn\">☰</button>\n        <div class=\"page-title\"><h1 id=\"topTitle\">Главная</h1><p id=\"topSubtitle\">Рабочий путь отдела блогеров</p></div>\n        <div class=\"top-search\"><span>⌕</span><input class=\"input\" id=\"globalSearch\" placeholder=\"Найти блогера, тег или сотрудника\"></div>\n        <div class=\"top-actions\">\n          <select class=\"select role-select hidden\" id=\"roleSwitcher\" title=\"Роль сотрудника\" disabled>\n            <option value=\"leader\">Администратор</option>\n            <option value=\"manager\">Менеджер</option>\n            <option value=\"assistant\">Ассистент</option>\n            <option value=\"analyst\">Аналитик</option>\n          </select>\n          <button class=\"btn btn-outline hidden\" id=\"installAppBtn\" type=\"button\" title=\"Установить приложение\">⇩ <span>Установить</span></button>\n          <button class=\"btn btn-primary\" id=\"quickAddBtn\">＋ <span>Добавить блогера</span></button>\n        </div>\n      </header>\n\n      <div class=\"content\">\n        <section class=\"page active\" id=\"page-dashboard\">\n          <div class=\"page-head\">\n            <div><h2>Центр управления отделом</h2><p>Главные показатели и последовательность ежедневной работы</p></div>\n            <div class=\"actions\">\n              <button class=\"btn btn-outline\" data-page-jump=\"reports\">Открыть сводку →</button>\n            </div>\n          </div>\n\n          <div class=\"card workflow-card\">\n            <div class=\"workflow-flow\">\n              <button class=\"workflow-step\" data-page-jump=\"bloggers\"><b>1</b><strong>Выбрать блогера</strong><span>База, категории и договоры</span></button>\n              <button class=\"workflow-step\" data-page-jump=\"placements\"><b>2</b><strong>Создать размещение</strong><span>ТЗ, условия и ответственный</span></button>\n              <button class=\"workflow-step\" data-page-jump=\"calendar\"><b>3</b><strong>Проверить выход</strong><span>Дата, прогрев и публикация</span></button>\n              <button class=\"workflow-step\" data-report-jump=\"actuals\"><b>4</b><strong>Внести охваты</strong><span>Факт и фото статистики</span></button>\n              <button class=\"workflow-step\" data-report-jump=\"daily\"><b>5</b><strong>Закрыть день</strong><span>Менеджеры и ассистенты</span></button>\n              <button class=\"workflow-step leader-only\" data-page-jump=\"kpi\"><b>6</b><strong>Рассчитать KPI</strong><span>План, факт и зарплата</span></button>\n            </div>\n          </div>\n\n          <div class=\"import-strip\" id=\"syncHealthStrip\" style=\"margin-top:12px\">\n            <strong id=\"syncHealthTitle\">↻ Проверяю синхронизацию данных</strong>\n            <span id=\"syncHealthMeta\">Карточки, размещения, выходы, отчёты и KPI используют единые показатели</span>\n          </div>\n\n          <article class=\"card card-pad\" id=\"departmentMonthControl\" style=\"margin-top:16px\">\n            <div class=\"card-title\">\n              <div><h3 id=\"departmentMonthTitle\">Рабочий месяц</h3><p id=\"departmentMonthHint\">Блогеры, размещения и выходы автоматически открываются за действующий период</p></div>\n              <div class=\"actions\"><span class=\"badge badge-green\" id=\"departmentMonthStatus\">Активен</span><button class=\"btn btn-sm btn-outline leader-only\" id=\"closeDepartmentMonthBtn\" type=\"button\">Закрыть месяц</button><button class=\"btn btn-sm btn-primary leader-only\" id=\"addNextDepartmentMonthBtn\" type=\"button\">Добавить следующий месяц</button></div>\n            </div>\n            <div class=\"quality-item\"><div><strong>Что произойдёт при закрытии</strong><small>Все данные сохранятся и перейдут в архив. Их можно открыть в базе блогеров, размещениях и выходах.</small></div><span class=\"badge badge-blue\">Без удаления данных</span></div>\n            <details id=\"departmentMonthArchiveDetails\" style=\"margin-top:14px\"><summary><b id=\"departmentMonthArchiveTitle\">Архив месяцев</b></summary><div class=\"quality-list\" id=\"departmentMonthArchive\" style=\"margin-top:12px\"></div></details>\n          </article>\n\n          <article class=\"card card-pad\" style=\"margin-top:16px\">\n            <div class=\"card-title\">\n              <div><h3 id=\"dashboardMonthTitle\">Сводка за текущий месяц</h3><p>На главной отображается только действующий месяц; факт обновляется по выходам и внесённым охватам</p></div>\n              <div class=\"actions\"><span class=\"badge badge-green\" id=\"dashboardMonthBadge\">Текущий месяц</span><button class=\"btn btn-sm btn-outline\" data-report-jump=\"monthly\">Подробнее →</button></div>\n            </div>\n            <div class=\"report-section-head\"><div><h3>Два отдела</h3><p>ЛН и FIT PRO рассчитаны отдельно по размещениям действующего месяца</p></div><span class=\"badge badge-blue\">Раздельный факт</span></div>\n            <div class=\"grid grid-2\" id=\"dashboardDirectionCards\"></div>\n            <div class=\"report-section-head\"><div><h3>Общий итог</h3><p>Сумма показателей ЛН и FIT PRO</p></div><span class=\"badge badge-green\">ЛН + FIT PRO</span></div>\n            <div class=\"grid grid-3\" id=\"dashboardMonthKpis\"></div>\n            <div class=\"report-section-head\"><div><h3>Рассылки отдела</h3><p>Общий план и факт менеджеров и ассистентов</p></div><span class=\"badge badge-green\">Обновляется после сохранения отчёта</span></div>\n            <div class=\"grid grid-4\" id=\"dashboardOutreachKpis\"></div>\n            <div class=\"report-section-head\"><div><h3>Менеджеры</h3><p>Рассылки за день и накопительный итог текущего месяца</p></div><div class=\"actions\"><label style=\"color:var(--muted);font-size:10px;font-weight:800\">День отчёта</label><select class=\"select\" id=\"dashboardOutreachDate\" style=\"width:auto\"></select></div></div>\n            <div class=\"table-wrap\"><table style=\"min-width:1520px\"><thead><tr><th>Менеджер</th><th>Рассылки за день: план / факт</th><th>Рассылки за месяц: план / факт</th><th>Выходы: план / факт</th><th>Охват: план / факт</th><th>Гарант / факт интеграций</th><th>Выполнение охвата</th><th>Выручка: план / факт</th><th>Выполнение выручки</th></tr></thead><tbody id=\"dashboardMonthManagers\"></tbody></table></div>\n            <div class=\"report-section-head\"><div><h3>Ассистенты</h3><p>Ежедневная работа и накопительный итог за действующий месяц</p></div><span class=\"badge badge-blue\" id=\"dashboardAssistantMonthBadge\">—</span></div>\n            <div class=\"table-wrap\"><table style=\"min-width:1050px\"><thead><tr><th>Ассистент</th><th>Закреплён за</th><th>День</th><th>За день: план / факт</th><th>Выполнение дня</th><th>За месяц: план / факт</th><th>Выполнение месяца</th></tr></thead><tbody id=\"dashboardAssistantOutreach\"></tbody></table></div>\n            <div class=\"table-note\" id=\"dashboardMonthNote\">Показатели рассчитываются автоматически по текущему месяцу.</div>\n          </article>\n\n          <div class=\"grid grid-3 dashboard-grid\" style=\"margin-top:16px\">\n            <article class=\"card card-pad\">\n              <div class=\"card-title\"><div><h3>Требуют внимания сегодня</h3><p>Каждое предупреждение открывает нужные размещения</p></div><span class=\"badge badge-red\">0</span></div>\n              <div class=\"alert-list\">\n                <div class=\"alert-item\"><span class=\"alert-icon alert-red\">!</span><div><strong>Нет договора</strong><small>Размещения нельзя выпускать без оформления</small></div><button class=\"more-btn\" data-placement-jump-filter=\"contract\">→</button></div>\n                <div class=\"alert-item\"><span class=\"alert-icon alert-amber\">⌛</span><div><strong>Ждём статистику</strong><small>Нет фактических охватов после выхода</small></div><button class=\"more-btn\" data-placement-jump-filter=\"stats\">→</button></div>\n                <div class=\"alert-item\"><span class=\"alert-icon alert-red\">↓</span><div><strong>Не выполнен гарант</strong><small>Нужно согласовать компенсационный выход</small></div><button class=\"more-btn\" data-placement-jump-filter=\"guarantee\">→</button></div>\n                <div class=\"alert-item\"><span class=\"alert-icon alert-blue\">✓</span><div><strong>Очередь согласований</strong><small>Новые блогеры и коммерческие условия</small></div><button class=\"more-btn\" data-placement-jump-filter=\"approval\">→</button></div>\n                <div class=\"alert-item\"><span class=\"alert-icon alert-blue\">i</span><div><strong>План / факт за месяц</strong><small>Факт обновляется автоматически каждый день</small></div><button class=\"more-btn\" data-page-jump=\"reports\">→</button></div>\n              </div>\n            </article>\n\n            <article class=\"card card-pad span-2\">\n              <div class=\"card-title\">\n                <div><h3>Эффективность блогеров</h3><p>Топ по выручке и количеству лидов</p></div>\n                <button class=\"btn btn-sm btn-outline\" data-page-jump=\"bloggers\">Вся база →</button>\n              </div>\n              <div class=\"table-wrap\">\n                <table style=\"min-width:650px\">\n                  <thead><tr><th>Блогер</th><th>Направление</th><th>Лиды</th><th>Продажи</th><th>Выручка</th><th>ROMI</th></tr></thead>\n                  <tbody id=\"topBloggers\"></tbody>\n                </table>\n              </div>\n            </article>\n\n          </div>\n        </section>\n\n        <section class=\"page\" id=\"page-profile\">\n          <div class=\"page-head\">\n            <div><h2 id=\"employeeProfilePageTitle\">Мой кабинет</h2><p>Роль, закрепление и результаты за текущий и прошлые месяцы</p></div>\n            <div class=\"actions\"><select class=\"select\" id=\"employeeProfileMonthFilter\" aria-label=\"Месяц показателей\"></select><button class=\"btn btn-outline leader-only hidden\" id=\"backToTeamBtn\" type=\"button\">← К сотрудникам</button></div>\n          </div>\n          <article class=\"card card-pad\">\n            <div class=\"profile-hero\">\n              <div class=\"profile-avatar\" id=\"employeeProfileAvatar\">НС</div>\n              <div><h3 id=\"employeeProfileName\">Сотрудник NSL</h3><p id=\"employeeProfileMeta\">Рабочая почта · роль</p></div>\n              <div class=\"profile-access\" id=\"employeeProfileBadges\"></div>\n            </div>\n          </article>\n          <div class=\"grid grid-4\" id=\"employeeProfileKpis\" style=\"margin-top:16px\"></div>\n          <article class=\"card table-card\" style=\"margin-top:16px\">\n            <div class=\"card-title card-pad\"><div><h3>История показателей</h3><p>Данные связываются с сотрудником по текущему имени и именам из старых отчётов</p></div><span class=\"badge badge-green\">Все месяцы</span></div>\n            <div class=\"table-wrap\"><table style=\"min-width:980px\"><thead><tr><th>Месяц</th><th>Роль</th><th>Рассылки</th><th>Выходы</th><th>Фактический охват</th><th>Согласия</th><th>Передано менеджеру</th><th>Источник</th></tr></thead><tbody id=\"employeeProfileHistory\"></tbody></table></div>\n          </article>\n        </section>\n\n        <section class=\"page leader-only\" id=\"page-finance\">\n          <div class=\"page-head\">\n            <div><h2>Финансы</h2><p>План, факт, затраты и эффективность отдела — только для администратора</p></div>\n            <div class=\"actions\">\n              <div class=\"segmented\" id=\"brandSwitch\">\n                <button class=\"segment active\" data-brand=\"ln\">ЛН</button>\n                <button class=\"segment\" data-brand=\"fit\">FIT PRO</button>\n                <button class=\"segment\" data-brand=\"all\">Все</button>\n              </div>\n              <button class=\"btn btn-sm btn-outline\" id=\"refreshFinanceBtn\" type=\"button\">↻ Обновить</button>\n            </div>\n          </div>\n          <div class=\"import-strip\"><strong>🔒 Доступ только администратору</strong><span>Данные обновляются из финансовой таблицы и не отображаются на главной</span></div>\n          <div class=\"grid grid-4\" id=\"financeKpiGrid\" style=\"margin-top:16px\"></div>\n          <article class=\"card card-pad\" id=\"financeTrendCard\" style=\"margin-top:16px\">\n            <div class=\"card-title\">\n              <div><h3>Динамика лидов и выручки</h3><p>По месяцам из финансовой сводки</p></div>\n              <div class=\"legend finance-trend-legend\"><span>Лиды</span><span>Выручка</span></div>\n            </div>\n            <div class=\"finance-trend-chart\" id=\"financeTrendChart\"><div class=\"empty-state\">Загружаю актуальные финансовые данные…</div></div>\n            <div class=\"table-note\" id=\"financeTrendNote\">График строится по факту из текущего и архивных месяцев.</div>\n          </article>\n          <article class=\"card card-pad\" id=\"financeCenter\" style=\"margin-top:16px\">\n            <div class=\"card-title\">\n              <div><h3 id=\"financeCenterTitle\">Финансы и результат отдела</h3><p>ЛН, FIT PRO и сводный итог по актуальному месяцу</p></div>\n              <div class=\"actions\"><span class=\"badge badge-green\" id=\"financeSyncStatus\">Обновление из Google Sheets</span></div>\n            </div>\n            <div class=\"grid grid-3\" id=\"financeDirectionCards\"></div>\n            <div class=\"report-section-head\"><div><h3>Сводная по всем показателям</h3><p>План и факт двух направлений; ROI и ROMI пересчитываются по общим затратам</p></div><span class=\"badge badge-green\">Защищённый источник</span></div>\n            <div class=\"table-wrap\"><table style=\"min-width:1260px\"><thead><tr><th>Показатель</th><th>ЛН · план</th><th>ЛН · факт</th><th>FIT PRO · план</th><th>FIT PRO · факт</th><th>Всего · план</th><th>Всего · факт</th><th>Выполнение</th></tr></thead><tbody id=\"financeMetricsTable\"></tbody></table></div>\n            <div class=\"table-note\" id=\"financeSourceNote\">Загружаю актуальные значения из листов «Отчет ЛН» и «Отчет FIT PRO»…</div>\n            <details style=\"margin-top:16px\" id=\"financeArchiveDetails\"><summary><b id=\"financeArchiveTitle\">Архив прошлых месяцев</b></summary><div id=\"financeArchive\" style=\"margin-top:12px\"></div></details>\n          </article>\n        </section>\n\n        <section class=\"page\" id=\"page-bloggers\">\n          <div class=\"page-head\">\n            <div><h2>База блогеров</h2><p>Единый справочник для ЛН и FIT PRO без дублей</p></div>\n            <div class=\"actions\"><button class=\"btn btn-outline\">⇩ Экспорт</button><button class=\"btn btn-outline leader-only hidden\" id=\"cancelBloggerEditBtn\">Отменить</button><button class=\"btn btn-outline leader-only\" id=\"toggleBloggerEditBtn\">✎ Редактировать таблицу</button><button class=\"btn btn-primary add-blogger-btn\">＋ Добавить блогера</button></div>\n          </div>\n          <div class=\"import-strip\"><strong>✓ Импортировано из Google Sheets</strong><span id=\"bloggerImportMeta\">Единая база без дублей · администратор может редактировать данные прямо в таблице</span></div>\n          <div class=\"card card-pad\">\n            <div class=\"toolbar\">\n              <input class=\"input\" id=\"bloggerSearch\" placeholder=\"Поиск по имени, ссылке или тегу\">\n              <select class=\"select\" id=\"bloggerMonthFilter\" style=\"width:auto\"><option value=\"\">Все месяцы</option></select>\n              <select class=\"select\" id=\"statusFilter\"><option value=\"\">Все статусы</option><option>Вышел</option><option>Тест</option><option>На оформлении</option><option>Отказ</option></select>\n              <select class=\"select\" id=\"managerFilter\"><option value=\"\">Все менеджеры</option></select>\n              <select class=\"select\" id=\"brandFilter\"><option value=\"\">Все направления</option><option>ЛН</option><option>FIT PRO</option></select>\n              <select class=\"select\" id=\"categoryFilter\"><option value=\"\">Все категории</option></select>\n              <span class=\"toolbar-spacer\"></span>\n              <span id=\"bloggerResultCount\" style=\"color:var(--muted);font-size:11px\"></span>\n              <div class=\"placement-filter-break\"></div>\n              <div class=\"filter-control\"><label>Площадка</label><select class=\"select\" id=\"bloggerPlatformFilter\"><option value=\"\">Все площадки</option><option value=\"ig\">Instagram</option><option value=\"tg\">Telegram</option><option value=\"vk\">VK</option></select></div>\n              <div class=\"filter-control\"><label>Договоры</label><select class=\"select\" id=\"bloggerContractFilter\"><option value=\"\">Любой статус</option><option value=\"all-ready\">Оба подписаны</option><option value=\"commercial\">Коммерческий подписан</option><option value=\"barter\">Бартерный подписан</option><option value=\"missing\">Нет подписанного</option><option value=\"processing\">На оформлении</option></select></div>\n              <div class=\"filter-control\"><label>Охват</label><div class=\"reach-filter\"><input class=\"input\" id=\"bloggerReachMin\" type=\"number\" min=\"0\" placeholder=\"От\"><input class=\"input\" id=\"bloggerReachMax\" type=\"number\" min=\"0\" placeholder=\"До\"></div></div>\n              <div class=\"filter-control\"><label>Минимум лидов</label><input class=\"input\" id=\"bloggerLeadsMin\" type=\"number\" min=\"0\" placeholder=\"Например, 10\"></div>\n              <div class=\"filter-control\"><label>Минимум продаж</label><input class=\"input\" id=\"bloggerSalesMin\" type=\"number\" min=\"0\" placeholder=\"Например, 1\"></div>\n              <div class=\"filter-control\"><label>Выручка от, ₽</label><input class=\"input\" id=\"bloggerRevenueMin\" type=\"number\" min=\"0\" placeholder=\"Например, 100000\"></div>\n              <div class=\"filter-control\"><label>Последний выход от</label><input class=\"input\" id=\"bloggerLastFrom\" type=\"date\"></div>\n              <div class=\"filter-control\"><label>Последний выход до</label><input class=\"input\" id=\"bloggerLastTo\" type=\"date\"></div>\n              <div class=\"filter-control\"><label>Сортировка</label><select class=\"select\" id=\"bloggerSortFilter\"><option value=\"created-desc\">Сначала добавленные</option><option value=\"name-asc\">По имени</option><option value=\"reach-desc\">Охват: больше</option><option value=\"reach-asc\">Охват: меньше</option><option value=\"leads-desc\">Лиды: больше</option><option value=\"sales-desc\">Продажи: больше</option><option value=\"revenue-desc\">Выручка: больше</option><option value=\"last-desc\">Последний выход</option></select></div>\n              <button class=\"btn btn-outline btn-sm\" id=\"resetBloggerFilters\" type=\"button\" style=\"align-self:flex-end\">Сбросить</button>\n            </div>\n          </div>\n          <div class=\"card table-card\" style=\"margin-top:12px\">\n            <div class=\"table-scroll-hint\"><span>←</span> Прокрутите таблицу вправо, чтобы увидеть все показатели <span>→</span></div>\n            <div class=\"table-wrap bloggers-table-scroll\" tabindex=\"0\" aria-label=\"Таблица блогеров с горизонтальной прокруткой\">\n              <table>\n                <thead><tr><th>Блогер</th><th>Направление</th><th>Площадки</th><th>Категория</th><th>Статус</th><th>Менеджер</th><th>Договор — коммерция</th><th>Договор — бартер</th><th>Охват</th><th>Лиды</th><th>Продажи</th><th>Выручка</th><th>Последний выход</th><th></th></tr></thead>\n                <tbody id=\"bloggersTable\"></tbody>\n              </table>\n            </div>\n            <div class=\"empty-state hidden\" id=\"bloggersEmpty\">По выбранным фильтрам блогеров не найдено.</div>\n          </div>\n        </section>\n\n        <section class=\"page\" id=\"page-placements\">\n          <div class=\"page-head\">\n            <div><h2>Единый реестр размещений</h2><p>Одна строка — одно размещение. Все форматы, документы и результаты раскрываются внутри карточки</p></div>\n            <div class=\"actions\"><button class=\"btn btn-primary\" id=\"addPlacementBtn\">＋ Новое размещение</button></div>\n          </div>\n          <div class=\"import-strip\"><strong>✓ Полный реестр размещений</strong><span id=\"placementImportMeta\">ЛН и FIT PRO в одной таблице · форматы хранятся внутри размещения</span></div>\n          <div class=\"card card-pad placement-toolbar\">\n            <input class=\"input\" id=\"placementSearch\" placeholder=\"Найти блогера\" style=\"width:190px\">\n            <select class=\"select\" id=\"placementMonthFilter\" style=\"width:auto\"><option value=\"\">Все месяцы</option></select>\n            <select class=\"select\" id=\"placementManagerFilter\" style=\"width:auto\"><option value=\"\">Все менеджеры</option></select>\n            <select class=\"select\" id=\"placementDecisionFilter\" style=\"width:auto\"><option value=\"\">Все решения</option><option>Оставляем</option><option>Убираем</option><option>На оценке</option></select>\n            <span class=\"toolbar-spacer\"></span><small style=\"color:var(--muted)\">Нажмите строку, чтобы открыть детали</small>\n            <div class=\"placement-filter-break\"></div>\n            <div class=\"filter-control\"><label>Направление</label><select class=\"select\" id=\"placementDirectionFilter\"><option value=\"\">Все</option><option>ЛН</option><option>FIT PRO</option><option>Оба</option></select></div>\n            <div class=\"filter-control\"><label>Сотрудничество</label><select class=\"select\" id=\"placementDealTypeFilter\"><option value=\"\">Все</option><option>Бартер</option><option>Коммерция</option><option>Смешанный</option></select></div>\n            <div class=\"filter-control\"><label>Текущий статус</label><select class=\"select\" id=\"placementStatusFilter\"><option value=\"\">Все статусы</option><option>Согласование</option><option>Ждём договор</option><option>Ждём ТЗ</option><option>Прогрев</option><option>Ждём статистику</option><option>Завершён</option><option>Отказ</option></select></div>\n            <div class=\"filter-control\"><label>Формат</label><select class=\"select\" id=\"placementFormatFilter\"><option value=\"\">Все форматы</option><option>Stories</option><option>Reels</option><option>Карусель</option><option>Telegram</option><option>VK</option><option>Дополнительный</option></select></div>\n            <div class=\"filter-control\"><label>Охват: факт или гарант</label><div class=\"reach-filter\"><input class=\"input\" id=\"placementReachMin\" type=\"number\" min=\"0\" placeholder=\"От\"><input class=\"input\" id=\"placementReachMax\" type=\"number\" min=\"0\" placeholder=\"До\"></div></div>\n            <div class=\"filter-control\"><label>Дата выхода от</label><input class=\"input\" id=\"placementDateFrom\" type=\"date\"></div>\n            <div class=\"filter-control\"><label>Дата выхода до</label><input class=\"input\" id=\"placementDateTo\" type=\"date\"></div>\n            <div class=\"filter-control\"><label>Договор</label><select class=\"select\" id=\"placementContractFilter\"><option value=\"\">Любой</option><option value=\"ready\">Готов / подписан</option><option value=\"missing\">Не готов</option></select></div>\n            <div class=\"filter-control\"><label>Сортировка</label><select class=\"select\" id=\"placementSortFilter\"><option value=\"created-desc\">Сначала добавленные</option><option value=\"date-desc\">По дате выхода: новые</option><option value=\"date-asc\">По дате выхода: старые</option><option value=\"reach-desc\">Охват: больше</option><option value=\"reach-asc\">Охват: меньше</option><option value=\"revenue-desc\">Выручка: больше</option></select></div>\n            <button class=\"btn btn-outline btn-sm\" id=\"resetPlacementFilters\" type=\"button\" style=\"align-self:flex-end\">Сбросить</button>\n            <span class=\"filter-result\" id=\"placementFilterCount\">Найдено: 0</span>\n          </div>\n\n          <div class=\"grid grid-4\" id=\"placementSummary\" style=\"margin-bottom:16px\"></div>\n\n          <div class=\"quick-filters\" id=\"placementQuickFilters\">\n            <button class=\"quick-filter active\" data-placement-quick=\"all\">Все</button><button class=\"quick-filter\" data-placement-quick=\"mine\">Мои блогеры</button><button class=\"quick-filter\" data-placement-quick=\"ln\">ЛН</button><button class=\"quick-filter\" data-placement-quick=\"fit\">FIT PRO</button><button class=\"quick-filter\" data-placement-quick=\"today\">Выходы сегодня</button><button class=\"quick-filter\" data-placement-quick=\"week\">На этой неделе</button><button class=\"quick-filter\" data-placement-quick=\"stats\">Ждём статистику</button><button class=\"quick-filter\" data-placement-quick=\"overdue\">Просрочено</button><button class=\"quick-filter\" data-placement-quick=\"contract\">Нет договора</button><button class=\"quick-filter\" data-placement-quick=\"guarantee\">Не выполнен гарант</button><button class=\"quick-filter\" data-placement-quick=\"barter\">Бартер</button><button class=\"quick-filter\" data-placement-quick=\"commercial\">Коммерция</button><button class=\"quick-filter\" data-placement-quick=\"repeat\">Повторные</button><button class=\"quick-filter\" data-placement-quick=\"approval\">На согласовании</button>\n          </div>\n          <div class=\"card table-card\">\n            <div class=\"table-wrap\"><table style=\"min-width:1480px\"><thead><tr><th></th><th>Размещение / блогер</th><th>Направление</th><th>Ниша</th><th>Менеджер</th><th>Сотрудничество</th><th>Дата выхода</th><th>Старт прогрева</th><th>Окончание прогрева</th><th>Гарант / факт</th><th>Текущий статус</th><th>Решение</th></tr></thead><tbody id=\"placementUnifiedTable\"></tbody></table></div>\n            <div class=\"pager\"><span id=\"placementUnifiedPagerText\"></span><div class=\"pager-actions\"><button class=\"btn btn-sm btn-outline\" id=\"placementUnifiedPrev\">←</button><button class=\"btn btn-sm btn-outline\" id=\"placementUnifiedNext\">→</button></div></div>\n            <div class=\"table-note\">Reels, Stories, карусель, Telegram и дополнительные выходы не дублируют реестр: они собраны в раскрываемом блоке «Форматы» конкретного размещения.</div>\n          </div>\n\n          <div class=\"placement-view hidden\" id=\"placement-view-plan\">\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:1180px\"><thead><tr><th>Дата начала</th><th>Прогрев</th><th>Блогер</th><th>Решение</th><th>Менеджер</th><th>Тип сделки</th><th>Источник</th><th>Статус подготовки</th></tr></thead><tbody id=\"placementPlanTable\"></tbody></table></div><div class=\"pager\"><span id=\"placementPagerText\"></span><div class=\"pager-actions\"><button class=\"btn btn-sm btn-outline\" id=\"placementPrev\">←</button><button class=\"btn btn-sm btn-outline\" id=\"placementNext\">→</button></div></div><div class=\"table-note\">Планирование содержит только даты, ответственного и решение по блогеру. Условия и результаты вынесены в отдельные вкладки.</div></div>\n          </div>\n\n          <div class=\"placement-view hidden\" id=\"placement-view-docs\">\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:1050px\"><thead><tr><th>Блогер</th><th>ФИО / карточка</th><th>ТЗ</th><th>Договор</th><th>Рабочий чат</th><th>Ответственный</th></tr></thead><tbody id=\"placementDocsTable\"></tbody></table></div><div class=\"table-note\">В публичной демоверсии персональные данные и приватные ссылки на чаты скрыты. В рабочем кабинете они будут доступны сотрудникам по ролям.</div></div>\n          </div>\n\n          <div class=\"placement-view hidden\" id=\"placement-view-terms\">\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:1100px\"><thead><tr><th>Блогер</th><th>Формат</th><th>Площадка</th><th>Тип размещения</th><th>Длительность</th><th>Стоимость</th><th>Гарантированный охват</th></tr></thead><tbody id=\"placementTermsTable\"></tbody></table></div></div>\n          </div>\n\n          <div class=\"placement-view hidden\" id=\"placement-view-results\">\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:1320px\"><thead><tr><th>Блогер</th><th>Гарант</th><th>Факт охвата</th><th>Выполнение</th><th>Клики</th><th>Лиды</th><th>Продажи</th><th>Выручка</th><th>Эффективность</th><th>Комментарий</th></tr></thead><tbody id=\"placementResultsTable\"></tbody></table></div><div class=\"table-note\">Фактический охват вводится сотрудником вручную после выхода — отдельно по каждому размещению и формату. Фото от блогера хранится в отчёте и подтверждает результат.</div></div>\n          </div>\n\n          <div class=\"placement-view hidden\" id=\"placement-view-reels\">\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:1260px\"><thead><tr><th>Дата</th><th>Блогер</th><th>Менеджер</th><th>Площадка</th><th>Статус</th><th>Договор</th><th>Гарант</th><th>Охват Reels</th><th>Охват карусели</th><th>Лиды</th><th>Продажи</th><th>Выручка</th><th>Публикация</th></tr></thead><tbody id=\"placementReelsTable\"></tbody></table></div><div class=\"table-note\">Reels и карусели загружены из отдельной вкладки. Закрытые чаты и персональные реквизиты не публикуются.</div></div>\n          </div>\n\n        </section>\n\n        <section class=\"page\" id=\"page-calendar\">\n          <div class=\"page-head\">\n            <div><h2>Выходы и календарь</h2><p>Публикации, прогревы, отметки и анкеты по датам</p></div>\n            <div class=\"actions\"><button class=\"btn btn-primary\" id=\"calendarAddBtn\">＋ Добавить выход</button></div>\n          </div>\n          <div class=\"import-strip\"><strong>✓ Список синхронизирован с карточками блогеров</strong><span id=\"exitImportMeta\"></span></div>\n          <div class=\"card card-pad\">\n            <div class=\"placement-toolbar\">\n              <input class=\"input\" id=\"exitSearch\" placeholder=\"Найти блогера\" style=\"width:190px\">\n              <select class=\"select\" id=\"exitMonthFilter\" style=\"width:auto\"><option value=\"\">Все месяцы</option></select>\n              <select class=\"select\" id=\"exitManagerFilter\" style=\"width:auto\"><option value=\"\">Все менеджеры</option></select>\n              <select class=\"select\" id=\"exitFormatFilter\" style=\"width:auto\"><option value=\"\">Все форматы</option></select>\n              <div class=\"placement-filter-break\"></div>\n              <div class=\"filter-control\"><label>Охват от</label><input class=\"input\" id=\"exitReachMin\" type=\"number\" min=\"0\" placeholder=\"0\"></div>\n              <div class=\"filter-control\"><label>Охват до</label><input class=\"input\" id=\"exitReachMax\" type=\"number\" min=\"0\" placeholder=\"Без ограничения\"></div>\n              <div class=\"filter-control\"><label>Дата от</label><input class=\"input\" id=\"exitDateFrom\" type=\"date\"></div>\n              <div class=\"filter-control\"><label>Дата до</label><input class=\"input\" id=\"exitDateTo\" type=\"date\"></div>\n              <div class=\"filter-control\"><label>Фактический охват</label><select class=\"select\" id=\"exitActualFilter\"><option value=\"\">Любой</option><option value=\"ready\">Внесён</option><option value=\"missing\">Ожидается</option></select></div>\n              <div class=\"filter-control\"><label>Сортировка</label><select class=\"select\" id=\"exitSortFilter\"><option value=\"created-desc\">Сначала добавленные</option><option value=\"date-desc\">По дате выхода: новые</option><option value=\"date-asc\">По дате выхода: старые</option><option value=\"reach-desc\">Охват: больше</option><option value=\"reach-asc\">Охват: меньше</option></select></div>\n              <button class=\"btn btn-outline btn-sm\" id=\"resetExitFilters\">Сбросить</button>\n              <span class=\"filter-result\" id=\"exitResultCount\">Найдено: 0</span>\n            </div>\n          </div>\n          <div class=\"card table-card\" style=\"margin-top:12px\"><div class=\"table-wrap\"><table style=\"min-width:1220px\"><thead><tr><th>Дата учёта</th><th>Блогер</th><th>Менеджер</th><th>Прогрев / день</th><th>Формат</th><th>Плановый охват</th><th>Фактический охват</th><th>Статус</th><th>Профиль</th><th>Действие</th></tr></thead><tbody id=\"weeklyExitsTable\"></tbody></table></div><div class=\"pager\"><span id=\"exitPagerText\"></span><div class=\"pager-actions\"><button class=\"btn btn-sm btn-outline\" id=\"exitPrev\">←</button><button class=\"btn btn-sm btn-outline\" id=\"exitNext\">→</button></div></div><div class=\"table-note\">Если у размещения задан период прогрева, оно отображается в «Выходах» каждый календарный день периода (например, 3/3, 5/5 или весь месяц). Само размещение и его фактический охват в KPI учитываются один раз. Удалять выходы может только администратор.</div></div>\n        </section>\n\n        <section class=\"page\" id=\"page-reports\">\n          <div class=\"page-head\">\n            <div><h2>Отчёты и контроль</h2><p>Дневная работа, месячные планы и фактические охваты — в отдельных разделах</p></div>\n            <button class=\"btn btn-outline\" id=\"managerExportBtn\">⇩ Выгрузить данные</button>\n          </div>\n\n          <div class=\"card report-nav\">\n            <div class=\"segmented\" id=\"reportViewSwitch\">\n              <button class=\"segment active\" data-report-view=\"daily\">За день</button>\n              <button class=\"segment\" data-report-view=\"monthly\">План / факт за месяц</button>\n              <button class=\"segment\" data-report-view=\"actuals\">Фактические охваты</button>\n            </div>\n            <p>Выберите нужный уровень контроля — остальные блоки не будут мешать работе.</p>\n          </div>\n\n          <div class=\"report-view\" id=\"report-view-daily\">\n            <div class=\"card context-toolbar\">\n              <div class=\"toolbar\">\n                <input class=\"input\" id=\"managerDailyDateFilter\" type=\"date\" style=\"width:auto\">\n                <select class=\"select\" id=\"managerMetricsFilter\" style=\"width:auto\"><option value=\"all\">Все сотрудники</option></select>\n                <span class=\"toolbar-spacer\"></span>\n                <button class=\"btn btn-outline\" id=\"fillAssistantReportBtn\">＋ Отчёт ассистента</button>\n                <button class=\"btn btn-primary\" id=\"fillReportBtn\">＋ Отчёт менеджера</button>\n              </div>\n            </div>\n\n            <div class=\"grid manager-kpis\" id=\"managerKpiGrid\"></div>\n            <div class=\"grid grid-3\" style=\"margin-top:16px\">\n              <article class=\"card card-pad span-2\">\n                <div class=\"card-title\"><div><h3>Воронка дня</h3><p>Конверсии между этапами работы менеджеров</p></div><span class=\"badge badge-green\" id=\"managerFunnelPeriod\">14.07.2026</span></div>\n                <div class=\"funnel-list\" id=\"managerFunnel\"></div>\n                <div class=\"metric-formulas\"><span class=\"metric-formula\"><b>Ответ:</b> ответы / рассылки</span><span class=\"metric-formula\"><b>Согласие:</b> согласия / ответы</span><span class=\"metric-formula\"><b>Выход:</b> выходы / согласия</span><span class=\"metric-formula\"><b>Подтверждение:</b> фотоотчёты / выходы</span></div>\n              </article>\n              <article class=\"card card-pad\"><div class=\"card-title\"><div><h3>Требует внимания</h3><p>Отклонения за выбранный день</p></div></div><div class=\"quality-list\" id=\"managerQuality\"></div></article>\n            </div>\n\n            <div class=\"report-section-head\"><div><h3>Менеджеры</h3><p>Отдельная запись за каждый день</p></div></div>\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:2340px\"><thead><tr><th>Менеджер</th><th>Дата</th><th>План / факт рассылок</th><th>Ответы</th><th>Конв. в ответ</th><th>Согласия</th><th>Согласия / ответы</th><th>Закрыто блогеров</th><th>Отказы</th><th>В диалоге</th><th>Выходы ЛН / FIT</th><th>План / факт охвата</th><th>% плана охвата</th><th>Доп. / Reels</th><th>Переносы</th><th>Вышли вовремя</th><th>Отчёты с фото</th><th>Договоры ком. / бартер</th><th>Факт ЛН</th><th>Факт FIT</th><th>Общий факт</th><th>% фин. плана</th></tr></thead><tbody id=\"managerMetricsTable\"></tbody></table></div><div class=\"table-note\">Финансовый факт поступает из amoCRM; охват засчитывается после добавления статистики. Исторические рассылки загружаются из защищённой общей базы.</div></div>\n\n            <div class=\"report-section-head\"><div><h3>Ассистенты</h3><p>Рассылки и передача блогеров закреплённому менеджеру</p></div></div>\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:1480px\"><thead><tr><th>Ассистент</th><th>Дата</th><th>Закреплён за</th><th>План рассылок</th><th>Факт</th><th>% плана</th><th>Ответы</th><th>Согласия</th><th>Отказы</th><th>В диалоге</th><th>Передано менеджеру</th><th>Конверсия в передачу</th><th>Комментарий</th><th>Статус дня</th></tr></thead><tbody id=\"assistantDailyTable\"></tbody></table></div><div class=\"table-note\">Отчёты ассистентов хранятся отдельно и не меняют показатели менеджеров.</div></div>\n          </div>\n\n          <div class=\"report-view hidden\" id=\"report-view-monthly\">\n            <div class=\"report-section-head\"><div><h3>План / факт по месяцам</h3><p>Администратор задаёт план, факт обновляется автоматически по вышедшим интеграциям</p></div><div class=\"actions\"><input class=\"input\" id=\"managerMonthlyPlanFilter\" type=\"month\" value=\"2026-07\" style=\"width:auto\"><span class=\"badge badge-green\" id=\"monthlyPlanFactBadge\">Факт обновлён автоматически</span></div></div>\n            <div class=\"grid manager-kpis\" id=\"monthlyPlanKpis\"></div>\n            <div class=\"card table-card\" style=\"margin-top:12px\"><div class=\"table-wrap\"><table style=\"min-width:1580px\"><thead><tr><th>Менеджер</th><th>План выходов</th><th>Факт выходов</th><th>% плана</th><th>План охвата</th><th>Гарант охвата</th><th>Факт охвата</th><th>% плана</th><th>План выручки</th><th>Факт выручки</th><th>% плана</th><th>Источник факта</th></tr></thead><tbody id=\"managerMonthlyPlanTable\"></tbody></table></div><div class=\"table-note\">План доступен администратору. Гарант и факт пересчитываются из Stories, Reels и каруселей всех менеджеров.</div></div>\n          </div>\n\n          <div class=\"report-view hidden\" id=\"report-view-actuals\">\n            <div class=\"report-section-head\"><div><h3>Фактические охваты</h3><p>Реальные охваты после выхода и скриншоты статистики</p></div><button class=\"btn btn-primary\" id=\"addEvidenceBtn\">＋ Добавить фактический охват</button></div>\n            <div class=\"card context-toolbar\" style=\"margin-bottom:12px\"><div class=\"toolbar\"><label for=\"evidenceEmployeeFilter\" style=\"font-size:11px;color:var(--muted)\">Сотрудник</label><select class=\"select\" id=\"evidenceEmployeeFilter\" style=\"width:auto\"><option value=\"all\">Все сотрудники</option></select><span class=\"toolbar-spacer\"></span><span class=\"badge badge-green\">Данные из вкладки «Сотрудники»</span></div></div>\n            <div class=\"card table-card\"><div class=\"card-title\" style=\"padding:18px 18px 0\"><div><h3>Отчёты по выходам</h3><p>Открывайте фото статистики прямо из таблицы</p></div><span class=\"badge badge-green\" id=\"evidenceCountBadge\">0 отчётов</span></div><div class=\"table-wrap\"><table style=\"min-width:800px\"><thead><tr><th>Блогер</th><th>Дата выхода</th><th>Фактический охват</th><th>Клики</th><th>Фото статистики</th><th>Добавил</th><th>Статус</th></tr></thead><tbody id=\"evidenceTable\"></tbody></table></div></div>\n          </div>\n        </section>\n\n        <section class=\"page leader-only\" id=\"page-kpi\">\n          <div class=\"page-head\">\n            <div><h2>KPI, зарплата и регламент</h2><p>Автоматический расчёт вознаграждения и единые правила работы отдела</p></div>\n            <div class=\"actions\"><span class=\"badge badge-green\">Доступ только администратору</span><button class=\"btn btn-outline\" id=\"openKpiRegulationBtn\" type=\"button\">Открыть защищённый PDF</button></div>\n          </div>\n          <article class=\"card kpi-regulation-hero\">\n            <div><span class=\"badge\">—</span><h3>Лига Нутрициологии · отдел по работе с блогерами</h3><p>Расчёт ведётся только по подтверждённым размещениям: нужен фактический выход, статистика, соблюдение ТЗ и обязательной маркировки. Отчётный период — календарный месяц.</p></div>\n            <div class=\"kpi-regulation-meta\"><div><strong>—</strong><span>план охвата на менеджера</span></div><div><strong>—</strong><span>максимум охватного KPI</span></div><div><strong>—</strong><span>срок получения статистики</span></div><div><strong>—</strong><span>утверждение KPI за месяц</span></div></div>\n          </article>\n\n          <div class=\"card card-pad\" style=\"margin-top:16px\"><div class=\"segmented\" id=\"regulationViewSwitch\"><button class=\"segment active\" data-regulation-view=\"salary\">Зарплата команды</button><button class=\"segment\" data-regulation-view=\"calculator\">Калькулятор KPI</button><button class=\"segment\" data-regulation-view=\"rules\">Регламент работы</button><button class=\"segment\" data-regulation-view=\"acceptance\">Приёмка выхода</button><button class=\"segment\" data-regulation-view=\"sanctions\">Санкции</button></div></div>\n\n          <div class=\"regulation-view\" id=\"regulation-view-salary\" style=\"margin-top:16px\">\n            <div class=\"report-section-head\"><div><h3>Автоматический расчёт зарплаты</h3><p>Оклад + KPI за блогеров + KPI за охват − санкции</p></div><div class=\"actions\"><select class=\"select\" id=\"salaryMonthFilter\" style=\"width:auto\"></select><span class=\"badge badge-green\">Автоматический расчёт</span></div></div>\n            <div class=\"grid grid-4\" id=\"salarySummaryGrid\" style=\"margin-bottom:16px\"></div>\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:1640px\"><thead><tr><th>Сотрудник</th><th>Роль</th><th>Оклад</th><th>—</th><th>—</th><th>—</th><th>Подтверждённый охват</th><th>% плана</th><th>KPI за блогеров</th><th>KPI за охват</th><th>Санкции</th><th>Итоговый KPI</th><th>Зарплата</th><th>Статус</th></tr></thead><tbody id=\"salaryTable\"></tbody></table></div><div class=\"table-note\">В расчёт попадают только активные сотрудники из раздела «Сотрудники». Для менеджеров факт и категории рассчитываются автоматически; администратор может вручную изменить сумму KPI за охват и санкции за выбранный месяц. У остальных ролей зарплата равна окладу.</div></div>\n          </div>\n\n          <div class=\"regulation-view hidden\" id=\"regulation-view-calculator\" style=\"margin-top:16px\">\n            <div class=\"grid grid-3\">\n              <article class=\"card card-pad span-2\">\n                <div class=\"card-title\"><div><h3>Калькулятор менеджера</h3><p>Автоматически использует те же данные и правила, что таблица зарплат</p></div><button class=\"btn btn-sm btn-outline\" id=\"loadKpiFromDataBtn\">↻ Пересчитать из базы</button></div>\n                <div class=\"form-grid\" style=\"margin-bottom:14px\"><div class=\"field\"><label>Менеджер</label><select class=\"select\" id=\"kpiManagerSelect\"></select></div><div class=\"field\"><label>Отчётный месяц</label><select class=\"select\" id=\"kpiMonthSelect\"></select></div></div>\n                <div class=\"kpi-form-grid\"><div class=\"field\"><label>—</label><input class=\"input kpi-calc-input\" id=\"kpiCategoryA\" type=\"number\" min=\"0\" value=\"0\" readonly></div><div class=\"field\"><label>—</label><input class=\"input kpi-calc-input\" id=\"kpiCategoryB\" type=\"number\" min=\"0\" value=\"0\" readonly></div><div class=\"field\"><label>—</label><input class=\"input kpi-calc-input\" id=\"kpiCategoryC\" type=\"number\" min=\"0\" value=\"0\" readonly></div><div class=\"field\"><label>Подтверждённый охват</label><input class=\"input kpi-calc-input\" id=\"kpiFactReach\" type=\"number\" min=\"0\" value=\"0\" readonly></div><div class=\"field\"><label>KPI за охват вручную, ₽</label><input class=\"input kpi-calc-input\" id=\"kpiManualReachAmount\" type=\"number\" min=\"0\" max=\"100000000\" step=\"1\" value=\"0\"></div><div class=\"field\"><label>Оклад из карточки, ₽</label><input class=\"input kpi-calc-input\" id=\"kpiBaseSalary\" type=\"number\" min=\"0\" value=\"0\" readonly></div><div class=\"field\"><label>Санкции за месяц, ₽</label><input class=\"input kpi-calc-input\" id=\"kpiSanctions\" type=\"number\" min=\"0\" value=\"0\"></div></div>\n                <p class=\"evidence-note\" id=\"kpiCalculatorSource\">Данные будут загружены из реестра размещений.</p>\n              </article>\n              <article class=\"card card-pad\"><div class=\"kpi-result-total\"><span>Итоговая зарплата</span><strong id=\"kpiSalaryAmount\">—</strong></div><div class=\"kpi-breakdown\"><div><span>KPI за блогеров</span><b id=\"kpiBloggersAmount\">—</b></div><div><span>Выполнение охвата</span><b id=\"kpiReachPercent\">—</b></div><div><span>KPI за охват</span><b id=\"kpiReachAmount\">—</b></div><div><span>Итоговый KPI</span><b id=\"kpiTotalAmount\">—</b></div></div></article>\n            </div>\n            <article class=\"card card-pad\" style=\"margin-top:16px\">\n              <div class=\"card-title\"><div><h3>Блогеры KPI по месяцам</h3><p>Администратор вручную формирует список для выбранного месяца. Блогеры из прошлого месяца не переносятся.</p></div><span class=\"badge badge-green\" id=\"kpiRosterMonthBadge\">Текущий месяц</span></div>\n              <div class=\"form-grid\" style=\"margin-bottom:14px\">\n                <div class=\"field\"><label>Блогер</label><select class=\"select\" id=\"kpiBloggerSelect\"></select></div>\n                <div class=\"field\"><label>Ответственный менеджер</label><select class=\"select\" id=\"kpiRosterManagerSelect\"></select></div>\n                <div class=\"field\"><label>Фактический охват за месяц</label><input class=\"input\" id=\"kpiBloggerReach\" type=\"number\" min=\"0\" max=\"1000000000\" value=\"0\"></div>\n                <div class=\"field\"><label>Комментарий</label><input class=\"input\" id=\"kpiBloggerNote\" type=\"text\" maxlength=\"1000\" placeholder=\"Необязательно\"></div>\n              </div>\n              <div class=\"actions\" style=\"margin-bottom:14px\"><button class=\"btn btn-primary\" id=\"addKpiBloggerBtn\" type=\"button\">＋ Добавить в KPI месяца</button></div>\n              <div class=\"table-wrap\"><table style=\"min-width:920px\"><thead><tr><th>Блогер</th><th>Месяц</th><th>Менеджер</th><th>Фактический охват</th><th>Категория</th><th>Комментарий</th><th></th></tr></thead><tbody id=\"kpiBloggerRosterTable\"></tbody></table></div>\n            </article>\n            <div class=\"card table-card\" style=\"margin-top:16px\"><div class=\"table-wrap\"><table><thead><tr><th>Выполнение плана</th><th>Подтверждённый охват</th><th>Оплата блока</th><th>Сумма</th></tr></thead><tbody><tr><td>—</td><td>—</td><td>Не начисляется</td><td><b>—</b></td></tr><tr><td>—</td><td>—</td><td>—</td><td><b>—</b></td></tr><tr><td>—</td><td>—</td><td>—</td><td><b>—</b></td></tr><tr><td>—</td><td>—</td><td>—</td><td><b>—</b></td></tr><tr><td>—</td><td>—</td><td>—</td><td><b>—</b></td></tr></tbody></table></div></div>\n          </div>\n\n          <div class=\"regulation-view hidden\" id=\"regulation-view-rules\" style=\"margin-top:16px\">\n            <div class=\"grid grid-2\"><article class=\"card card-pad\"><div class=\"card-title\"><div><h3>Обязательный порядок работы</h3><p>От первого контакта до финальной статистики</p></div></div><div class=\"regulation-list\"><div class=\"regulation-item\"><strong>—</strong><p>Целевая аудитория, тематика, география, охваты, вовлечённость, рекламная нагрузка и репутационные риски.</p></div><div class=\"regulation-item\"><strong>—</strong><p>Формат, дата, стоимость или бартер, гарантированный охват и состав интеграции.</p></div><div class=\"regulation-item\"><strong>—</strong><p>Передать актуальное ТЗ, согласовать материалы и получить готовность маркировки до выхода.</p></div><div class=\"regulation-item\"><strong>—</strong><p>Проверить дату, оффер, ссылку, отметки, обязательные смыслы и рекламную маркировку.</p></div><div class=\"regulation-item\"><strong>—</strong><p>—</p></div></div></article><article class=\"card card-pad\"><div class=\"card-title\"><div><h3>Роли и ответственность</h3><p>Кто отвечает за каждый блок</p></div></div><div class=\"regulation-list\"><div class=\"regulation-item\"><strong>Руководитель отдела</strong><p>Планирование, утверждение блогеров и условий, контроль планов, финальное согласование KPI и спорные ситуации.</p></div><div class=\"regulation-item\"><strong>Менеджер по блогерам</strong><p>Поиск, проверка, коммуникация, условия, контроль выхода, сбор статистики и отчётных материалов.</p></div><div class=\"regulation-item\"><strong>Ответственный за маркировку</strong><p>Подготовка токенов и данных, проверка корректной маркировки перед выходом.</p></div><div class=\"regulation-item\"><strong>Юрист / документы</strong><p>Договорные условия, закрывающие документы, счета, чеки и подтверждения.</p></div></div></article></div>\n          </div>\n\n          <div class=\"regulation-view hidden\" id=\"regulation-view-acceptance\" style=\"margin-top:16px\">\n            <div class=\"grid grid-2\"><article class=\"card card-pad\"><div class=\"card-title\"><div><h3>Условия зачёта в KPI</h3><p>Все обязательные пункты должны быть выполнены</p></div><span class=\"badge badge-red\" id=\"acceptanceStatus\">Не зачтено</span></div><div id=\"acceptanceChecklist\"><label class=\"acceptance-check\"><input type=\"checkbox\">Размещение фактически вышло</label><label class=\"acceptance-check\"><input type=\"checkbox\">Есть ссылка или запись опубликованного материала</label><label class=\"acceptance-check\"><input type=\"checkbox\">Получена подтверждённая статистика</label><label class=\"acceptance-check\"><input type=\"checkbox\">Соблюдены ТЗ, оффер, ссылка и формат</label><label class=\"acceptance-check\"><input type=\"checkbox\">Проверена обязательная маркировка рекламы</label><label class=\"acceptance-check\"><input type=\"checkbox\">—</label></div></article><article class=\"card table-card\"><div class=\"table-wrap\"><table><thead><tr><th>Формат</th><th>Что подтверждаем</th></tr></thead><tbody><tr><td><b>Stories</b></td><td>Ссылка/запись, скриншоты, дата и время, просмотры после завершения.</td></tr><tr><td><b>Telegram-пост</b></td><td>Ссылка, просмотры, дата, сохранность поста в согласованный период.</td></tr><tr><td><b>Reels / Shorts / VK-клип</b></td><td>Ссылка, дата, просмотры/охваты, соблюдение ТЗ и маркировки.</td></tr><tr><td><b>Комбинированная интеграция</b></td><td>Каждый элемент отдельно: сторис, пост, ролик, ссылка, статистика и маркировка.</td></tr></tbody></table></div></article></div>\n          </div>\n\n          <div class=\"regulation-view hidden\" id=\"regulation-view-sanctions\" style=\"margin-top:16px\">\n            <div class=\"card table-card\"><div class=\"table-wrap\"><table style=\"min-width:1000px\"><thead><tr><th>Нарушение</th><th>Последствие / санкция</th></tr></thead><tbody><tr><td>Нет статистики</td><td>—</td></tr><tr><td>Статистика передана несвоевременно</td><td>—</td></tr><tr><td>Нарушение маркировки по вине менеджера</td><td>—</td></tr><tr><td>Выход без согласованного ТЗ / ссылки / смыслов</td><td>—</td></tr><tr><td>Срыв даты выхода по вине менеджера</td><td>—</td></tr><tr><td>Запуск без согласования при риске</td><td>—</td></tr><tr><td>Нет отчётных данных по задачам и результатам</td><td>—</td></tr><tr><td>Некорректные данные или завышение охватов</td><td>—</td></tr><tr><td>Нарушены договорные / финансовые условия</td><td>—</td></tr><tr><td>Репутационный риск в коммуникации</td><td>—</td></tr></tbody></table></div><div class=\"table-note\">—</div></div>\n            <div class=\"report-section-head\"><div><h3>Порядок утверждения</h3><p>Итоговый расчёт за предыдущий месяц</p></div></div><div class=\"approval-flow\"><div class=\"approval-step\"><b>—</b><span>Формируется расчёт только по подтверждённым размещениям.</span></div><div class=\"approval-step\"><b>—</b><span>Планы, качество данных, нарушения и применимые санкции.</span></div><div class=\"approval-step\"><b>—</b><span>Генеральный директор или уполномоченное лицо.</span></div><div class=\"approval-step\"><b>—</b><span>Утверждённая сумма передаётся к выплате.</span></div></div>\n          </div>\n        </section>\n\n        <section class=\"page\" id=\"page-team\">\n          <div class=\"page-head\">\n            <div><h2>Сотрудники и доступы</h2><p>Кабинеты, роли, планы и зарплаты</p></div>\n            <div class=\"actions\"><button class=\"btn btn-primary\" id=\"inviteBtn\">＋ Пригласить сотрудника</button></div>\n          </div>\n          <div class=\"card card-pad\" style=\"margin-bottom:16px\"><div class=\"quality-item\"><div><strong>Персональный доступ для каждого сотрудника</strong><small>Добавьте сотрудника, сформируйте одноразовую ссылку регистрации и отправьте её сотруднику. История старых месяцев сохранится в его кабинете.</small></div><span class=\"badge badge-green\">Роли назначаются автоматически</span></div></div>\n          <div class=\"grid grid-3\" id=\"teamGrid\"></div>\n        </section>\n\n        <section class=\"page\" id=\"page-integrations\">\n          <div class=\"page-head\">\n            <div><h2>Интеграции</h2><p>Автоматический обмен данными и контроль качества</p></div>\n            <div class=\"actions\"><button class=\"btn btn-outline\" id=\"syncAllBtn\">↻ Синхронизировать всё</button></div>\n          </div>\n          <div class=\"grid grid-2\">\n            <article class=\"card integration\"><div class=\"integration-logo\">amo</div><div><h4>amoCRM</h4><p>Лиды, статусы, продажи, выручка и деньги в кассу</p></div><div class=\"integration-actions\"><span class=\"badge badge-green\">Подключено</span><small class=\"sync-time\">Статус появится после входа</small></div></article>\n            <article class=\"card integration\"><div class=\"integration-logo\">G</div><div><h4>Google Таблицы</h4><p>Исторический импорт базы и резервная выгрузка</p></div><div class=\"integration-actions\"><span class=\"badge badge-amber\">Импорт</span><small class=\"sync-time\">Доступно после входа</small></div></article>\n          </div>\n          <div class=\"grid grid-2\" style=\"margin-top:16px\">\n            <article class=\"card card-pad\">\n              <div class=\"card-title\"><div><h3>Сопоставление amoCRM</h3><p>Как поля сделки попадают в систему</p></div><button class=\"btn btn-sm btn-outline\">Настроить</button></div>\n              <div class=\"mapping\"><code>utm_content</code><span>→</span><code>Тег / ID блогера</code></div>\n              <div class=\"mapping\"><code>pipeline_id</code><span>→</span><code>Направление ЛН / FIT PRO</code></div>\n              <div class=\"mapping\"><code>status_id</code><span>→</span><code>Статус лида</code></div>\n              <div class=\"mapping\"><code>sale / cash</code><span>→</span><code>Выручка / деньги в кассу</code></div>\n            </article>\n            <article class=\"card card-pad\">\n              <div class=\"card-title\"><div><h3>Качество атрибуции</h3><p>Лиды без корректной связи с блогером</p></div><span class=\"badge badge-red\">Критично</span></div>\n              <div style=\"display:flex;align-items:end;gap:14px;margin:20px 0\"><strong style=\"font-size:38px;letter-spacing:-.05em\">—</strong><span style=\"color:var(--muted);padding-bottom:6px\">Данные появятся после входа</span></div>\n              <div class=\"progress\" style=\"height:11px\"><i style=\"width:0;background:var(--red)\"></i></div>\n              <p style=\"color:var(--muted);font-size:11px;line-height:1.55;margin:16px 0\">Программа будет создавать уникальную метку для каждого размещения и проверять её наличие до публикации.</p>\n              <button class=\"btn btn-outline btn-block\" id=\"openUtmRulesBtn\">Открыть правила UTM</button>\n            </article>\n          </div>\n        </section>\n      </div>\n    </main>\n    <nav class=\"mobile-bottom-nav\" aria-label=\"Основные разделы\">\n      <button class=\"mobile-nav-btn active\" type=\"button\" data-mobile-page=\"dashboard\"><b>⌂</b><span>Главная</span></button>\n      <button class=\"mobile-nav-btn\" type=\"button\" data-mobile-page=\"bloggers\"><b>Б</b><span>Блогеры</span></button>\n      <button class=\"mobile-nav-btn\" type=\"button\" data-mobile-page=\"placements\"><b>Р</b><span>Размещения</span></button>\n      <button class=\"mobile-nav-btn\" type=\"button\" data-mobile-page=\"calendar\"><b>В</b><span>Выходы</span></button>\n      <button class=\"mobile-nav-btn\" type=\"button\" data-mobile-page=\"reports\"><b>О</b><span>Отчёты</span></button>\n    </nav>\n  </div>\n\n  <div class=\"overlay\" id=\"overlay\"></div>\n\n  <aside class=\"drawer\" id=\"bloggerDrawer\">\n    <div class=\"drawer-head\"><div class=\"avatar\" id=\"drawerAvatar\">Б</div><div><h3 id=\"drawerName\">@блогер</h3><p id=\"drawerMeta\">Карточка блогера</p></div><button class=\"close-btn close-layer\">×</button></div>\n    <div class=\"drawer-tabs\"><button class=\"drawer-tab active\" data-drawer-view=\"card\">Карточка</button><button class=\"drawer-tab\" data-drawer-view=\"placements\">Размещения</button><button class=\"drawer-tab\" data-drawer-view=\"analytics\">Аналитика</button><button class=\"drawer-tab\" data-drawer-view=\"documents\">Документы</button></div>\n    <div class=\"drawer-body drawer-view\" id=\"drawerViewCard\">\n      <div class=\"drawer-section\"><h4>Основные данные</h4><div class=\"form-grid\">\n        <div class=\"field\"><label>Название / тег</label><input class=\"input\" id=\"editName\"></div>\n        <div class=\"field\"><label>Менеджер</label><select class=\"select\" id=\"editManager\"></select></div>\n        <div class=\"field field-wide\"><label>Ссылка на основную площадку</label><input class=\"input\" id=\"editLink\"></div>\n        <div class=\"field field-wide\"><label>Площадки блогера — можно выбрать несколько</label><div class=\"format-multi\" id=\"editPlatformChoices\">\n          <label class=\"format-choice\"><input type=\"checkbox\" value=\"ig\" data-edit-platform><span>Instagram</span></label>\n          <label class=\"format-choice\"><input type=\"checkbox\" value=\"tg\" data-edit-platform><span>Telegram</span></label>\n          <label class=\"format-choice\"><input type=\"checkbox\" value=\"vk\" data-edit-platform><span>VK</span></label>\n        </div></div>\n        <div class=\"field\"><label>Направление</label><select class=\"select\" id=\"editBrand\"><option>ЛН</option><option>FIT PRO</option><option>Оба</option></select></div>\n        <div class=\"field\"><label>Статус</label><select class=\"select\" id=\"editStatus\"><option>Вышел</option><option>Тест</option><option>На оформлении</option><option>Отказ</option></select></div>\n        <div class=\"field\"><label>Договор — коммерция</label><select class=\"select\" id=\"editCommercialContract\"><option>Подписан</option><option>На оформлении</option><option>Нет</option></select></div>\n        <div class=\"field\"><label>Договор — бартер</label><select class=\"select\" id=\"editBarterContract\"><option>Подписан</option><option>На оформлении</option><option>Нет</option></select></div>\n      </div></div>\n      <div class=\"drawer-section\"><h4>Аудитория и допуск</h4><div class=\"form-grid\">\n        <div class=\"field\"><label>Итоговый фактический охват</label><input class=\"input\" id=\"editReach\" type=\"number\" readonly><small>Факт вводится вручную по Stories, Reels, карусели и постам. Здесь автоматически отображается их сумма.</small></div>\n        <div class=\"field\"><label>ER, %</label><input class=\"input\" value=\"\"></div>\n        <div class=\"field\"><label>Аудитория РФ, %</label><input class=\"input\" value=\"\"></div>\n        <div class=\"field\"><label>Активная аудитория, %</label><input class=\"input\" value=\"\"></div>\n      </div></div>\n      <div class=\"drawer-section\"><h4>Фактические охваты</h4><div class=\"form-grid\">\n        <div class=\"field field-wide\"><label>Выход / размещение</label><select class=\"select\" id=\"cardActualPlacement\"></select></div>\n        <div class=\"field\"><label>Дата старта прогрева</label><input class=\"input\" id=\"cardWarmupStart\" type=\"date\"></div>\n        <div class=\"field\"><label>Дата окончания прогрева</label><input class=\"input\" id=\"cardWarmupEnd\" type=\"date\"></div>\n        <div class=\"field field-wide\"><div class=\"actions\"><button class=\"btn btn-outline\" type=\"button\" id=\"saveCardWarmupBtn\">Сохранить даты прогрева</button><span class=\"evidence-note\" id=\"cardWarmupSaveStatus\" style=\"display:none;margin:0\"></span></div></div>\n        <div class=\"field field-wide\"><label>Источники охвата — можно выбрать несколько</label><div class=\"format-multi\" id=\"cardActualFormatChoices\"></div></div>\n        <div class=\"field field-wide\"><div class=\"format-inputs\" id=\"cardActualFormatInputs\"></div></div>\n        <div class=\"field field-wide\" id=\"cardActualFormatSummary\"></div>\n        <div class=\"field field-wide\" style=\"align-items:flex-end\"><button class=\"btn btn-primary\" type=\"button\" id=\"saveCardActualBtn\">Сохранить выбранные охваты</button></div>\n        <div class=\"field field-wide\"><div class=\"evidence-note\" id=\"cardActualSaveStatus\" style=\"display:none;margin:0\"></div></div>\n      </div><p class=\"evidence-note\"><b>Ручной ввод:</b> выберите размещение, отметьте один или несколько форматов и внесите фактический охват по каждому. Программа только складывает сохранённые значения и передаёт сумму в сводки, KPI и расчёт зарплаты.</p></div>\n      <div class=\"drawer-section\"><h4>Коммерция и расходы</h4><div class=\"form-grid\">\n        <div class=\"field\"><label>Тип сотрудничества</label><select class=\"select\" id=\"editCooperationType\"><option>Коммерция</option><option>Бартер</option><option>Смешанный</option></select></div>\n        <div class=\"field\"><label>Потрачено всего, ₽</label><input class=\"input\" id=\"editSpent\" type=\"number\" min=\"0\" step=\"1\"></div>\n        <div class=\"field field-wide\"><p class=\"evidence-note\" id=\"trackedSpendNote\" style=\"margin:0\">Расходы из реестра размещений будут показаны здесь.</p></div>\n      </div></div>\n      <div class=\"drawer-section\"><h4>Договоры</h4>\n        <div class=\"contract-upload\">\n          <div class=\"field\"><label>Тип договора</label><select class=\"select\" id=\"contractUploadType\"><option value=\"commercial\">Коммерческий</option><option value=\"barter\">Бартерный</option></select></div>\n          <div class=\"field\"><label>Прикрепить файл</label><input class=\"input\" id=\"contractUploadFile\" type=\"file\" accept=\".pdf,.doc,.docx,.jpg,.jpeg,.png,.webp\"></div>\n        </div>\n        <div class=\"contract-file-list\" id=\"cardContractFileList\"></div>\n        <p class=\"evidence-note\">PDF, DOC, DOCX или изображение до 15 МБ. Договор сохраняется в карточке и отображается во вкладке «Документы».</p>\n      </div>\n      <div class=\"drawer-section\"><h4>Экономика</h4><div class=\"grid grid-3\">\n        <div class=\"team-stat\"><strong id=\"drawerSpent\">0 ₽</strong><span>потрачено</span></div><div class=\"team-stat\"><strong id=\"drawerRevenue\">0 ₽</strong><span>выручка</span></div><div class=\"team-stat\"><strong id=\"drawerLeads\">0</strong><span>лидов</span></div><div class=\"team-stat\"><strong id=\"drawerSales\">0</strong><span>продаж</span></div>\n      </div></div>\n      <div class=\"drawer-section\"><h4>Комментарий</h4><textarea class=\"textarea\" id=\"editComment\" maxlength=\"1500\" placeholder=\"Комментарий по блогеру, источник и рабочие заметки\"></textarea></div>\n    </div>\n    <div class=\"drawer-body drawer-view hidden\" id=\"drawerViewPlacements\"><div class=\"drawer-section\"><h4>История размещений</h4><div class=\"table-wrap\"><table style=\"min-width:720px\"><thead><tr><th>Дата</th><th>Формат</th><th>Гарант</th><th>Факт</th><th>Лиды</th><th>Продажи</th><th>Решение</th></tr></thead><tbody id=\"drawerPlacementHistory\"></tbody></table></div></div></div>\n    <div class=\"drawer-body drawer-view hidden\" id=\"drawerViewAnalytics\"><div class=\"drawer-section\"><h4>Среднее по последним 3 размещениям</h4><div class=\"grid grid-3\" id=\"drawerHistoryAverages\"></div></div><div class=\"drawer-section\"><h4>Итог по сотрудничеству</h4><div id=\"drawerHistoryDecision\"></div></div></div>\n    <div class=\"drawer-body drawer-view hidden\" id=\"drawerViewDocuments\"><div class=\"drawer-section\"><h4>Документы и готовность</h4><div id=\"drawerDocumentHistory\"></div></div></div>\n    <div class=\"drawer-foot\" id=\"drawerFoot\"><button class=\"btn btn-outline close-layer\">Отмена</button><button class=\"btn btn-primary\" id=\"saveBloggerBtn\">Сохранить изменения</button></div>\n  </aside>\n\n  <div class=\"modal\" id=\"addBloggerModal\">\n    <div class=\"modal-head\"><h3>Новый блогер</h3><button class=\"close-btn close-layer\">×</button></div>\n    <form id=\"addBloggerForm\">\n      <div class=\"modal-body\"><div class=\"form-grid\">\n        <div class=\"field\"><label>Название / тег</label><input class=\"input\" id=\"newName\" placeholder=\"@blogger\" required></div>\n        <div class=\"field\"><label>Менеджер</label><select class=\"select\" id=\"newManager\"></select></div>\n        <div class=\"field field-wide\"><label>Ссылка на площадку</label><input class=\"input\" id=\"newLink\" placeholder=\"https://instagram.com/...\" required></div>\n        <div class=\"field\"><label>Направление</label><select class=\"select\" id=\"newBrand\"><option>ЛН</option><option>FIT PRO</option></select></div>\n        <div class=\"field field-wide\"><label>Площадки — можно выбрать несколько</label><div class=\"format-multi\" id=\"newPlatformChoices\">\n          <label class=\"format-choice\"><input type=\"checkbox\" value=\"ig\" data-new-platform checked><span>Instagram</span></label>\n          <label class=\"format-choice\"><input type=\"checkbox\" value=\"tg\" data-new-platform><span>Telegram</span></label>\n          <label class=\"format-choice\"><input type=\"checkbox\" value=\"vk\" data-new-platform><span>VK</span></label>\n        </div></div>\n        <div class=\"field\"><label>Средний охват</label><input class=\"input\" id=\"newReach\" type=\"number\" value=\"0\"></div>\n        <div class=\"field\"><label>Статус</label><select class=\"select\" id=\"newStatus\"><option>Тест</option><option>Вышел</option><option>На оформлении</option></select></div>\n        <div class=\"field\"><label>Договор — коммерция</label><select class=\"select\" id=\"newCommercialContract\"><option>Нет</option><option>На оформлении</option><option>Подписан</option></select></div>\n        <div class=\"field\"><label>Договор — бартер</label><select class=\"select\" id=\"newBarterContract\"><option>Нет</option><option>На оформлении</option><option>Подписан</option></select></div>\n        <div class=\"field field-wide\"><label>Комментарий</label><textarea class=\"textarea\" id=\"newComment\" maxlength=\"1500\" placeholder=\"Источник, условия и рабочие заметки\"></textarea></div>\n      </div></div>\n      <div class=\"modal-foot\"><button type=\"button\" class=\"btn btn-outline close-layer\">Отмена</button><button class=\"btn btn-primary\" type=\"submit\">Создать карточку</button></div>\n    </form>\n  </div>\n\n  <div class=\"modal modal-wide\" id=\"addPlacementModal\">\n    <div class=\"modal-head\"><div><h3>Новое размещение</h3><p style=\"margin:4px 0 0;color:var(--muted);font-size:11px\">Сначала выберите блогера из общей базы</p></div><button class=\"close-btn close-layer\">×</button></div>\n    <form id=\"addPlacementForm\">\n      <div class=\"modal-body\">\n        <div class=\"form-grid\">\n          <div class=\"field field-wide\"><label>1. Найдите блогера по нику</label><input class=\"input\" id=\"newPlacementBloggerSearch\" type=\"search\" autocomplete=\"off\" placeholder=\"Например, @katya.dnk, имя или ссылка\"></div>\n          <div class=\"field field-wide\"><label>Найденные блогеры</label><select class=\"select\" id=\"newPlacementBlogger\" required></select><small id=\"newPlacementBloggerSearchMeta\">Можно искать по @нику, имени или ссылке</small></div>\n          <div class=\"field field-wide\"><div class=\"selected-blogger-preview\"><div><strong id=\"newPlacementBloggerName\">Блогер не выбран</strong><small id=\"newPlacementBloggerMeta\">Направление, менеджер и площадка</small></div><button class=\"btn btn-sm btn-outline\" type=\"button\" id=\"openSelectedBloggerBtn\">Открыть карточку →</button></div></div>\n          <div class=\"field\"><label>Дата выхода</label><input class=\"input\" id=\"newPlacementDate\" type=\"date\" required></div>\n          <div class=\"field\"><label>Формат</label><select class=\"select\" id=\"newPlacementFormat\"><option>Stories</option><option>Reels</option><option>Карусель / пост</option><option>Telegram</option><option>VK / Shorts</option><option>Дополнительный выход</option></select></div>\n          <div class=\"field\"><label>Ответственный сотрудник</label><select class=\"select\" id=\"newPlacementManager\"></select></div>\n          <div class=\"field\"><label>Направление</label><select class=\"select\" id=\"newPlacementDirection\"><option>ЛН</option><option>FIT PRO</option><option>Оба</option></select></div>\n          <div class=\"field\"><label>Тип сотрудничества</label><select class=\"select\" id=\"newPlacementDealType\"><option>Бартер</option><option>Коммерция</option><option>Смешанный</option></select></div>\n          <div class=\"field\"><label>Стоимость, ₽</label><input class=\"input\" id=\"newPlacementCost\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field\"><label>Гарантированный охват</label><input class=\"input\" id=\"newPlacementGuarantee\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field\"><label>Дата старта прогрева</label><input class=\"input\" id=\"newPlacementWarmupStart\" type=\"date\" required></div>\n          <div class=\"field\"><label>Дата окончания прогрева</label><input class=\"input\" id=\"newPlacementWarmupEnd\" type=\"date\" required></div>\n          <div class=\"field\"><label>Статус ТЗ</label><select class=\"select\" id=\"newPlacementBrief\"><option>Нет ТЗ</option><option>В работе</option><option>Готово</option></select></div>\n          <div class=\"field\"><label>Договор</label><select class=\"select\" id=\"newPlacementContract\"><option>Запрос данных</option><option>На оформлении</option><option>Готов</option><option>Подписан</option></select></div>\n          <div class=\"field\"><label>Решение</label><select class=\"select\" id=\"newPlacementDecision\"><option>На оценке</option><option>Оставляем</option><option>Убираем</option></select></div>\n          <div class=\"field field-wide\"><label>Рабочий комментарий</label><textarea class=\"textarea\" id=\"newPlacementComment\" placeholder=\"Условия, договорённости, особенности блогера\"></textarea></div>\n        </div>\n      </div>\n      <div class=\"modal-foot\"><button type=\"button\" class=\"btn btn-outline close-layer\">Отмена</button><button class=\"btn btn-primary\" type=\"submit\">Создать размещение</button></div>\n    </form>\n  </div>\n\n  <div class=\"modal modal-wide\" id=\"reportModal\">\n    <div class=\"modal-head\"><h3>Ежедневный отчёт менеджера</h3><button class=\"close-btn close-layer\">×</button></div>\n    <form class=\"modal-body\" id=\"dailyReportForm\">\n      <div class=\"form-grid\">\n        <div class=\"field\"><label>Дата</label><input class=\"input\" id=\"reportDate\" type=\"date\"></div>\n        <div class=\"field\"><label>Менеджер</label><select class=\"select\" id=\"reportManager\"></select></div>\n        <div class=\"field\"><label>План рассылок</label><input class=\"input\" id=\"reportPlanOutreach\" type=\"number\" min=\"0\" value=\"0\"></div>\n        <div class=\"field\"><label>Факт рассылок</label><input class=\"input\" id=\"reportOutreach\" type=\"number\" value=\"0\"></div>\n        <div class=\"field\"><label>Ответы</label><input class=\"input\" id=\"reportReplies\" type=\"number\" value=\"0\"></div>\n        <div class=\"field\"><label>Согласия</label><input class=\"input\" id=\"reportApprovals\" type=\"number\" value=\"0\"></div>\n        <div class=\"field\"><label>Отказы</label><input class=\"input\" id=\"reportRefusals\" type=\"number\" value=\"0\"></div>\n        <div class=\"field\"><label>Блогеры в диалоге</label><input class=\"input\" id=\"reportDialog\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Выходы ЛН</label><input class=\"input\" id=\"reportExitsLn\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Выходы FIT PRO</label><input class=\"input\" id=\"reportExitsFit\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Плановый охват ЛН</label><input class=\"input\" id=\"reportPlanReachLn\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Фактический охват ЛН</label><input class=\"input\" id=\"reportFactReachLn\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Плановый охват FIT PRO</label><input class=\"input\" id=\"reportPlanReachFit\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Фактический охват FIT PRO</label><input class=\"input\" id=\"reportFactReachFit\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Дополнительные отметки</label><input class=\"input\" id=\"reportExtraTags\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Reels / ролики</label><input class=\"input\" id=\"reportReels\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Переносы</label><input class=\"input\" id=\"reportTransfers\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Выходы вовремя</label><input class=\"input\" id=\"reportOnTime\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Отчёты с фото</label><input class=\"input\" id=\"reportEvidence\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Договоры — коммерция</label><input class=\"input\" id=\"reportCommercial\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Договоры — бартер</label><input class=\"input\" id=\"reportBarter\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Финансовый факт ЛН, ₽</label><input class=\"input\" id=\"reportRevenueLn\" type=\"number\" value=\"0\"></div>\n        <div class=\"field daily-auto-field\"><label>Финансовый факт FIT PRO, ₽</label><input class=\"input\" id=\"reportRevenueFit\" type=\"number\" value=\"0\"></div>\n        <div class=\"field field-wide\"><label>Короткий комментарий</label><textarea class=\"textarea\" id=\"reportComment\" placeholder=\"Что повлияло на результат дня\"></textarea></div>\n      </div>\n      <p class=\"evidence-note\">Менеджер вручную заполняет только активность и комментарий. Выходы, охваты, форматы, переносы, договоры и выручка рассчитываются автоматически по реестру, отчётам и данным amoCRM.</p>\n      <div style=\"display:flex;justify-content:flex-end;gap:9px;margin-top:8px\"><button type=\"button\" class=\"btn btn-outline close-layer\">Отмена</button><button type=\"submit\" class=\"btn btn-primary\">Сохранить отчёт</button></div>\n    </form>\n  </div>\n\n  <div class=\"modal\" id=\"assistantReportModal\">\n    <div class=\"modal-head\"><h3>Ежедневный отчёт ассистента</h3><button class=\"close-btn close-layer\">×</button></div>\n    <form id=\"assistantDailyReportForm\">\n      <div class=\"modal-body\">\n        <div class=\"form-grid\">\n          <div class=\"field\"><label>Дата</label><input class=\"input\" id=\"assistantReportDate\" type=\"date\" required></div>\n          <div class=\"field\"><label>Ассистент</label><select class=\"select\" id=\"assistantReportName\"></select></div>\n          <div class=\"field\"><label>Закреплённый менеджер</label><select class=\"select\" id=\"assistantReportManager\"></select></div>\n          <div class=\"field\"><label>План рассылок</label><input class=\"input\" id=\"assistantReportPlan\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field\"><label>Факт рассылок</label><input class=\"input\" id=\"assistantReportFact\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field\"><label>Ответы</label><input class=\"input\" id=\"assistantReportReplies\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field\"><label>Согласия</label><input class=\"input\" id=\"assistantReportApprovals\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field\"><label>Отказы</label><input class=\"input\" id=\"assistantReportRefusals\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field\"><label>Блогеры в диалоге</label><input class=\"input\" id=\"assistantReportDialog\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field\"><label>Передано менеджеру</label><input class=\"input\" id=\"assistantReportTransferred\" type=\"number\" min=\"0\" value=\"0\"></div>\n          <div class=\"field field-wide\"><label>Короткий комментарий</label><textarea class=\"textarea\" id=\"assistantReportComment\" placeholder=\"Что повлияло на результат дня\"></textarea></div>\n        </div>\n      </div>\n      <div class=\"modal-foot\"><button type=\"button\" class=\"btn btn-outline close-layer\">Отмена</button><button class=\"btn btn-primary\" type=\"submit\">Сохранить отчёт</button></div>\n    </form>\n  </div>\n\n  <div class=\"modal\" id=\"evidenceModal\">\n    <div class=\"modal-head\"><h3>Отчёт по выходу блогера</h3><button class=\"close-btn close-layer\">×</button></div>\n    <form id=\"evidenceForm\">\n      <div class=\"modal-body\">\n        <div class=\"form-grid\">\n          <div class=\"field\"><label>Блогер</label><select class=\"select\" id=\"evidenceBlogger\" required></select></div>\n          <div class=\"field\"><label>Дата выхода</label><input class=\"input\" id=\"evidenceDate\" type=\"date\" required></div>\n          <div class=\"field field-wide\"><label>Сотрудник</label><select class=\"select\" id=\"evidenceEmployee\" required></select><span style=\"font-size:10px;color:var(--muted)\">Список автоматически обновляется из раздела «Сотрудники»</span></div>\n          <div class=\"field\"><label>Фактический охват</label><input class=\"input\" id=\"evidenceReach\" type=\"number\" min=\"0\" placeholder=\"Введите значение\" required></div>\n          <div class=\"field\"><label>Клики</label><input class=\"input\" id=\"evidenceClicks\" type=\"number\" min=\"0\" placeholder=\"Введите значение\"></div>\n          <div class=\"field field-wide\">\n            <label>Фото и скриншоты от блогера</label>\n            <div class=\"upload-zone\">\n              <input id=\"evidenceFiles\" type=\"file\" accept=\"image/jpeg,image/png,image/webp\" multiple>\n              <strong>Выберите сразу несколько фотографий</strong>\n              <span>Можно добавлять повторно · до 10 файлов JPG, PNG или WEBP</span>\n            </div>\n            <div class=\"evidence-upload-status\"><span>Файлы добавляются к уже выбранным</span><strong id=\"evidenceUploadCount\">Выбрано 0 из 10</strong></div>\n            <div class=\"evidence-preview\" id=\"evidencePreview\"></div>\n            <p class=\"evidence-note\">Фотографии сохраняются в общем хранилище отчёта. Нажмите на скриншот после сохранения, чтобы посмотреть его целиком без обрезки.</p>\n          </div>\n          <div class=\"field field-wide\"><label>Комментарий</label><textarea class=\"textarea\" id=\"evidenceComment\" placeholder=\"Например: статистика за 24 часа после выхода\"></textarea></div>\n        </div>\n      </div>\n      <div class=\"modal-foot\"><button type=\"button\" class=\"btn btn-outline close-layer\">Отмена</button><button class=\"btn btn-primary\" id=\"saveEvidenceBtn\" type=\"submit\">Сохранить фактический охват</button></div>\n    </form>\n  </div>\n\n  <div class=\"modal evidence-viewer-modal\" id=\"evidenceViewerModal\">\n    <div class=\"modal-head\"><h3 id=\"evidenceViewerTitle\">Фактические охваты</h3><button class=\"close-btn close-layer\">×</button></div>\n    <div class=\"modal-body\">\n      <div class=\"evidence-gallery\" id=\"evidenceViewerGallery\"></div>\n      <p class=\"evidence-note\" id=\"evidenceViewerMeta\"></p>\n    </div>\n  </div>\n\n  <div class=\"modal\" id=\"infoModal\">\n    <div class=\"modal-head\"><h3 id=\"infoTitle\">Новый объект</h3><button class=\"close-btn close-layer\">×</button></div>\n    <div class=\"modal-body\"><p id=\"infoText\" style=\"color:var(--muted);line-height:1.6;margin:0\"></p></div>\n    <div class=\"modal-foot\"><button class=\"btn btn-primary close-layer\">Понятно</button></div>\n  </div>\n\n  <div class=\"modal\" id=\"employeeModal\">\n    <div class=\"modal-head\"><h3 id=\"employeeModalTitle\">Редактировать сотрудника</h3><button class=\"close-btn close-layer\">×</button></div>\n    <form id=\"employeeForm\">\n      <div class=\"modal-body\">\n        <input type=\"hidden\" id=\"employeeId\">\n        <div class=\"form-grid\">\n          <div class=\"field\"><label>Имя сотрудника</label><input class=\"input\" id=\"employeeName\" required maxlength=\"80\"></div>\n          <div class=\"field\"><label>Рабочая почта</label><input class=\"input\" id=\"employeeEmail\" type=\"email\" required maxlength=\"160\"></div>\n          <div class=\"field\"><label>Роль</label><select class=\"select\" id=\"employeeRole\"><option value=\"manager\">Менеджер</option><option value=\"assistant\">Ассистент</option><option value=\"analyst\">Аналитик</option><option value=\"leader\">Администратор</option></select></div>\n          <div class=\"field\"><label>Статус кабинета</label><select class=\"select\" id=\"employeeStatus\"><option value=\"active\">Активен</option><option value=\"paused\">Приостановлен</option></select></div>\n          <div class=\"field\" id=\"employeeManagerField\"><label>Закреплён за менеджером</label><select class=\"select\" id=\"employeeAssignedManager\"></select></div>\n          <div class=\"field\"><label>Оклад, ₽</label><input class=\"input\" id=\"employeeBaseSalary\" type=\"number\" min=\"0\" step=\"1\" value=\"0\"></div>\n          <div class=\"field field-wide\"><label>Имена в старых отчётах</label><input class=\"input\" id=\"employeeHistoryAliases\" maxlength=\"500\" placeholder=\"Например: прежнее имя сотрудника\"></div>\n        </div>\n        <p class=\"evidence-note\" id=\"employeeFormNote\">Имена из старых отчётов позволяют автоматически перенести статистику прошлых месяцев в личный кабинет.</p>\n      </div>\n      <div class=\"modal-foot\"><button type=\"button\" class=\"btn btn-outline close-layer\">Отмена</button><button type=\"button\" class=\"btn btn-outline hidden\" id=\"removeEmployeeBtn\">Удалить сотрудника</button><button class=\"btn btn-primary\" id=\"saveEmployeeBtn\" type=\"submit\">Сохранить сотрудника</button></div>\n    </form>\n  </div>\n\n  <div class=\"modal\" id=\"employeeAccessModal\">\n    <div class=\"modal-head\"><h3>Персональный доступ сотрудника</h3><button class=\"close-btn close-layer\">×</button></div>\n    <div class=\"modal-body\">\n      <p id=\"employeeAccessText\" style=\"margin:0 0 16px;color:var(--muted);line-height:1.6\"></p>\n      <div class=\"access-link-row\"><input class=\"input\" id=\"employeeAccessLink\" readonly><button class=\"btn btn-primary\" id=\"copyEmployeeAccessBtn\" type=\"button\">Копировать ссылку</button></div>\n      <div class=\"access-status\"><span>Ссылка действует 7 дней и используется один раз</span><span class=\"badge badge-amber\" id=\"employeeAccessExpiry\">7 дней</span></div>\n    </div>\n    <div class=\"modal-foot\"><button class=\"btn btn-outline close-layer\" type=\"button\">Готово</button></div>\n  </div>\n\n  <div class=\"toast\" id=\"toast\">Изменения сохранены</div>\n";
